import{_ as o,c as r,o as d,a2 as n}from"./chunks/framework.CHomSxuB.js";const i=JSON.parse('{"title":"7. 模拟盘执行线：卖出口径三票裁决与双点闭环","description":"","frontmatter":{},"headers":[],"relativePath":"A股量化验证/7-模拟盘执行线.md","filePath":"A股量化验证/7-模拟盘执行线.md"}'),s={name:"A股量化验证/7-模拟盘执行线.md"};function g(a,t,e,l,h,u){return d(),r("div",null,t[0]||(t[0]=[n('<h1 id="_7-模拟盘执行线-卖出口径三票裁决与双点闭环" tabindex="-1">7. 模拟盘执行线：卖出口径三票裁决与双点闭环 <a class="header-anchor" href="#_7-模拟盘执行线-卖出口径三票裁决与双点闭环" aria-label="Permalink to &quot;7. 模拟盘执行线：卖出口径三票裁决与双点闭环&quot;">​</a></h1><blockquote><p>研究线（Step 1→4）回答&quot;信号有没有 edge&quot;，执行线回答&quot;edge 能不能装进一个按真实规则运转的小账户&quot;。 2026-09-02，卖出口径经三轮回测裁决（E1/E2/E3），结论收敛为三个字——<strong>不折腾</strong>：不装止损、不走封板顺延、卖出统一放次日尾盘。 裁决日期：2026-09-02 ｜ 状态：🔴 运行中 —— V1.0 冻结（09-03 起）+ <strong>V1.1 记账本化（2026-09-03）+ 双任务口径定稿（2026-09-05）</strong>； 截至 <strong>2026-09-24</strong>：连续 <strong>13 个交易日 B 空仓</strong>后闸门于 09-21 放行、<strong>连续 2 日触发 A 单</strong>（一正一负）， 09-23/09-24 回归 B 空仓；累计 <strong>7 笔 A 单</strong>、连亏计数 1/3；并于 09-17 完成一次<strong>连续 12 日空仓的归因复盘</strong>（见 §三·复盘）</p></blockquote><p><a href="/A股量化验证/">返回 A股量化验证 首页</a></p><hr><h2 id="一、执行线在补什么" tabindex="-1">一、执行线在补什么 <a class="header-anchor" href="#一、执行线在补什么" aria-label="Permalink to &quot;一、执行线在补什么&quot;">​</a></h2><p>Step 4 前向追踪用<strong>理论价</strong>（信号日收盘价买入 → T+1 收盘卖出）判断信号有没有 edge， 但&quot;收盘价&quot;在真实世界排不进单——只能市价/限价成交。模拟盘就是补上这段的执行器：</p><ul><li>候选：前一日收盘涨停池，经机械漏斗过滤（含现金预检），开盘后 09:31 决策买入（记账价 = 决策时点现价）；开盘 ≥ 昨收 × 1.095 视为排不进单 → 弃单（与 Step 4 一字闸同值）；</li><li>卖出（记账价）：次交易日 <strong>14:57 尾盘现价 ≈ 当日收盘价</strong>（A 股 T+1，最早可卖日）；</li><li>记账（V1.1 起，见 §三）：只记两个时点单价，<strong>系统不算收益、不扣摩擦</strong>；连亏 ≥ 3 笔熔断停手；</li><li>超额基准：对标中证 1000（000852），口径与 Step 4 相同。</li></ul><p>买入规则沿用冻结纪律。执行线自己只多了一个待裁决问题——<strong>卖出时刻要不要&quot;优化&quot;</strong>。</p><h2 id="二、要裁决的问题" tabindex="-1">二、要裁决的问题 <a class="header-anchor" href="#二、要裁决的问题" aria-label="Permalink to &quot;二、要裁决的问题&quot;">​</a></h2><p>&quot;次日卖出&quot;常见的优化有四类：破位止损（Kill）、封板顺延持有（Lock）、盘中择时（Time-out）、尾盘统一卖（EOD）。 直觉上&quot;动态卖出&quot;应该加分，2026-09-02 用三组数据逐条验证 （口径：T 日涨停收盘买入 → T+1 卖出，扣双边摩擦，与 Step 4 Ev 同构）：</p><h3 id="e1-·-历史真成交-5-笔-开盘卖-vs-收盘卖-n-5-2026-09-02" tabindex="-1">E1 · 历史真成交 5 笔：开盘卖 vs 收盘卖（n=5，2026-09-02） <a class="header-anchor" href="#e1-·-历史真成交-5-笔-开盘卖-vs-收盘卖-n-5-2026-09-02" aria-label="Permalink to &quot;E1 · 历史真成交 5 笔：开盘卖 vs 收盘卖（n=5，2026-09-02）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>卖出点</th><th>平均收益</th><th>胜率</th></tr></thead><tbody><tr><td>T+1 收盘卖</td><td>+10.46%</td><td>5/5</td></tr><tr><td>T+1 开盘卖</td><td>+8.24%</td><td>4/5</td></tr></tbody></table><p>差约 +2.2pp/笔，其中约九成来自单笔&quot;低开高走大阳&quot;；反向证据同样存在 （高开低走的一笔，开盘卖保住 +13.21%，收盘卖只剩 +3.77%）。 结构规律：T+1 收阳 → 收盘卖优（4/4）；高开低走 → 开盘卖优（1/1）。<strong>n=5 不足以裁决，仅作方向参考。</strong></p><h3 id="e2-·-卖出状态机全量裁决-16-745-样本-244-交易日-全涨停生态-2026-09-02" tabindex="-1">E2 · 卖出状态机全量裁决（16,745 样本 / 244 交易日，全涨停生态，2026-09-02） <a class="header-anchor" href="#e2-·-卖出状态机全量裁决-16-745-样本-244-交易日-全涨停生态-2026-09-02" aria-label="Permalink to &quot;E2 · 卖出状态机全量裁决（16,745 样本 / 244 交易日，全涨停生态，2026-09-02）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>方案</th><th>相对&quot;静态收盘卖&quot;贡献</th><th>结论</th></tr></thead><tbody><tr><td>组合状态机</td><td>+0.80pp</td><td>增量<strong>全部</strong>来自 Lock</td></tr><tr><td>其中：封板顺延（Lock）</td><td>+0.96pp（顺延样本 3,061）</td><td>唯一正贡献来源</td></tr><tr><td>单独装止损（Kill-Loss）</td><td><strong>−0.16pp</strong></td><td>止损系统性卖在坑里</td></tr><tr><td>尾盘统一卖（EOD）</td><td>≈ 0</td><td>与静态收盘卖同价，纯纪律</td></tr></tbody></table><p>Kill 为什么是负的？A 股涨停股 T+1 深跌多为<strong>低开修复型</strong>：开盘砸出坑、盘中回升， 固定时点（尾盘）卖出恰好躲过坑底；止损则把单子精确成交在坑里 （细分：KILL_OPEN n=396、KILL_INTRADAY n=3,744，两组均为负）。</p><h3 id="e3-·-lock-专项裁决-全历史-t-1-收盘仍封板样本-n-3-158-2026-09-02" tabindex="-1">E3 · Lock 专项裁决（全历史 T+1 收盘仍封板样本 n=3,158，2026-09-02） <a class="header-anchor" href="#e3-·-lock-专项裁决-全历史-t-1-收盘仍封板样本-n-3-158-2026-09-02" aria-label="Permalink to &quot;E3 · Lock 专项裁决（全历史 T+1 收盘仍封板样本 n=3,158，2026-09-02）&quot;">​</a></h3><p>10cm 首板子集（n=1,651）四种卖出路径的全程收益：</p><table tabindex="0"><thead><tr><th>路径</th><th>收益</th></tr></thead><tbody><tr><td>A · T+1 收盘卖</td><td>+10.04%</td></tr><tr><td>C · 固定多持 1 天</td><td>+12.64%</td></tr><tr><td>Bc · 一路持有到断板日收盘</td><td>+14.98%</td></tr><tr><td>Bo · 断板日开盘卖</td><td>+18.21%（断板日约 40% 低开 → 偏乐观基准，Bc 才是可执行基准）</td></tr></tbody></table><p>顺延增量（Bc − A）<strong>均值 +4.94pp，中位数仅 +1.30pp</strong>（p25 −3.3% / p75 +8.0%）→ 增量极右偏， 由约 14% 走出 ≥3 板的样本撑起；最差 5% 增量 −0.33pp → 无大亏尾，但持仓周期从 1 天拉长到 ~2.5 天。</p><p>定性：Lock 是干净的正期望，但本质是一笔<strong>用 25% 概率少赚 3.3pp、换 14% 概率多赚 8pp+ 的右尾赌局</strong>， 且必须无条件持有到断板才成立（中途止损会摧毁其收益结构）——属策略级变更，不是&quot;卖出触发器&quot;。</p><h2 id="三、三票定稿-2026-09-02-与-v1-0-冻结" tabindex="-1">三、三票定稿（2026-09-02）与 V1.0 冻结 <a class="header-anchor" href="#三、三票定稿-2026-09-02-与-v1-0-冻结" aria-label="Permalink to &quot;三、三票定稿（2026-09-02）与 V1.0 冻结&quot;">​</a></h2><table tabindex="0"><thead><tr><th>选项</th><th>票</th><th>依据</th></tr></thead><tbody><tr><td>卖出点 = 次日尾盘（EOD / 14:57）</td><td>✅ 装</td><td>与静态收盘卖等价（E2）；与 Step 4 理论口径同构、账本可对账；顺带拆成独立结算任务</td></tr><tr><td>止损（Kill-Loss）</td><td>❌ 不装</td><td>E2：−0.16pp，保费视角不成立</td></tr><tr><td>封板顺延（Lock）</td><td>📦 归档</td><td>E3：正期望但极右偏 + 持仓周期变更；要试必须走预注册，禁止直接并入</td></tr></tbody></table><p><strong>执行线 V1.0 就此冻结</strong>（2026-09-03 起运行）：09:31 决策买入 + 14:57 尾盘结算，卖出无 Kill、无 Lock。</p><h3 id="v1-1-修订-2026-09-03-记账本化-只记单价不算收益" tabindex="-1">V1.1 修订（2026-09-03）：记账本化，只记单价不算收益 <a class="header-anchor" href="#v1-1-修订-2026-09-03-记账本化-只记单价不算收益" aria-label="Permalink to &quot;V1.1 修订（2026-09-03）：记账本化，只记单价不算收益&quot;">​</a></h3><p>首个验证日当天，执行通道从&quot;撮合服务&quot;整体改为<strong>账本直记</strong>，形成 V1.1：</p><ul><li><strong>账本即账户</strong>：现金/在途/连亏全部由账本推导，执行线不再依赖任何本地撮合服务，外部依赖清零；</li><li><strong>只记两个时点单价</strong>：买入价 = 决策时点现价（≈当日开盘），卖出价 = 次交易日 14:57 尾盘现价（≈当日收盘）；</li><li><strong>系统不算收益、不扣摩擦</strong>：记账与评价分离，收益由事后按单价自行核算——模拟盘不再产生&quot;自己的收益口径&quot;，与 Step 4 理论口径的对账回到纯价格层面；</li><li><strong>历史行统一取价</strong>：既往 A 单按同口径重列两时刻单价（买入日开盘 / 次日收盘），原收益字段清空，账本 append-only 未被触碰。</li></ul><h3 id="v1-1-实战运行-2026-09-03-09-24-13-日-b-空仓-→-闸门放行-2-笔" tabindex="-1">V1.1 实战运行（2026-09-03 ~ 09-24）：13 日 B 空仓 → 闸门放行 2 笔 <a class="header-anchor" href="#v1-1-实战运行-2026-09-03-09-24-13-日-b-空仓-→-闸门放行-2-笔" aria-label="Permalink to &quot;V1.1 实战运行（2026-09-03 ~ 09-24）：13 日 B 空仓 → 闸门放行 2 笔&quot;">​</a></h3><p>首个验证日（09-03）起，执行线连续 <strong>13 个交易日判 B（空仓）</strong>，触发原因高度一致：</p><table tabindex="0"><thead><tr><th>交易日</th><th>决策</th><th>触发原因（一句话）</th></tr></thead><tbody><tr><td>09-02</td><td>B</td><td>最高标竞价断板 → 闸门关</td></tr><tr><td>09-03</td><td>B</td><td>最高标竞价 ≈ 跌停开盘断板 → 闸门关</td></tr><tr><td>09-04</td><td>B</td><td>最高标低开断板 + 高位梯队集体退潮</td></tr><tr><td>09-07</td><td>B</td><td>最高标低开断板（设备故障延迟补录）</td></tr><tr><td>09-08</td><td>B</td><td>最高标高开未续板断板</td></tr><tr><td>09-09</td><td>B</td><td>最高标低开断板 + 主线一日游退潮</td></tr><tr><td>09-10</td><td>B</td><td>最高标冲高即回落断板 + 候选可买性差</td></tr><tr><td>09-11</td><td>B</td><td>最高标高开回落断板 + A 组无有效可买</td></tr><tr><td>09-14</td><td>B</td><td>最高标（4 天 4 板一字板）一字开盘后炸板崩跌 → 一字板崩塌式断板</td></tr><tr><td>09-15</td><td>B</td><td>最高标（6 天 5 板反包板）高开 +6.4% 后崩至 −9.8%、全天未触涨停 → 断板</td></tr><tr><td>09-16</td><td>B</td><td>最高标高开冲高未封即回落 → 断板；昨日一字板信号次日跌停开盘</td></tr><tr><td>09-17</td><td>B</td><td>最高标<strong>跌停开盘封死</strong>（前一日午后回封后次日直接跌停）→ 断板；主线无延续</td></tr><tr><td>09-18</td><td>B</td><td>最高标低开断板 + 并列最高连板同步断板 → 高度天花板双双失守</td></tr><tr><td><strong>09-21</strong></td><td><strong>A</strong></td><td><strong>最高连板一字续板未断 + 主线延续 + 首选顺位可买 → 闸门放行</strong></td></tr><tr><td><strong>09-22</strong></td><td><strong>A</strong></td><td><strong>同上（连续第 2 日）</strong></td></tr><tr><td>09-23</td><td>B</td><td>最高连板一字板今日开板、冲高未封即回落 → 断板（并列高度同步未续板）</td></tr><tr><td>09-24</td><td>B</td><td>最高连板（9 天 7 板）低开走弱、未触涨停 → 断板</td></tr></tbody></table><p>共同结构：<strong>13 个空仓日里，最高标几乎每天都在断板/易主</strong>，环境闸门按纪律关闭；个别日子候选组虽有 &quot;勉强可买&quot;的票（如冲板后封死），但&quot;断板日纪律优先&quot;写死在预案里，<strong>执行时不犹豫</strong>。 账本上 A 单累计 <strong>7 笔</strong>——<strong>空仓也是操作，而且是最常被执行的那一种</strong>（17 个交易日里 15 天 B）。</p><blockquote><p>⚠️ 纪律提醒（写进运行记录）：<strong>连续空仓不是降低门槛的理由</strong>。十三天不动手恰恰说明闸门在工作； 一旦因为&quot;太久没开张&quot;而放行弱候选，执行线就退化成情绪盘，V1.1 攒样本的意义随之归零。 09-21 的放行<strong>不是&quot;空太久了所以开一单&quot;，而是四条件（最高标未断板 / 主线延续 / 首选顺位可买 / 开盘不弱于阈值） 当天真的同时满足</strong>——这正是复盘后要验证的东西（见下）。</p></blockquote><h3 id="闸门首次放行-13-日空仓之后的两笔-a-单-2026-09-21-09-23" tabindex="-1">闸门首次放行：13 日空仓之后的两笔 A 单（2026-09-21 ~ 09-23） <a class="header-anchor" href="#闸门首次放行-13-日空仓之后的两笔-a-单-2026-09-21-09-23" aria-label="Permalink to &quot;闸门首次放行：13 日空仓之后的两笔 A 单（2026-09-21 ~ 09-23）&quot;">​</a></h3><p>09-21、09-22 连续两日触发 A 单，是执行线<strong>第一次对&quot;闸门是不是对的&quot;做前向检验</strong> （复盘的反事实结论说&quot;闸门挡掉的是净亏损&quot;，但反事实不是实测）。结果如下：</p><table tabindex="0"><thead><tr><th>信号日</th><th>标的</th><th>买入记账价</th><th>卖出记账价（次日 14:57）</th><th>价差</th></tr></thead><tbody><tr><td>09-21</td><td>天津普林</td><td>26.83</td><td>26.95</td><td><strong>+0.45%</strong></td></tr><tr><td>09-22</td><td>澳洋健康</td><td>6.04</td><td>5.38</td><td><strong>−10.93%</strong></td></tr></tbody></table><p>两笔均值 <strong>−5.24%</strong>（n=2，<strong>账本只记单价、系统不算收益、不扣摩擦</strong>，价差由统计层事后推导）。</p><p><strong>读法（重要）</strong>：</p><ul><li><strong>n=2 什么都证明不了</strong>，既不能说闸门错、也不能说闸门对——<strong>这一栏只作记录，不作结论</strong>；</li><li>但它与复盘的反事实（10 笔均值 −1.72%）方向一致：<strong>闸门放开的那两天，市场给的是负期望</strong>；</li><li>单笔结构值得记一笔：两笔都是&quot;最高标未断板 + 主线延续&quot;的干净开仓条件， 但一笔几乎打平、一笔大幅走弱——<strong>说明开仓条件的正确性只能靠大样本检验，单笔结果全是噪声</strong>；</li><li>澳洋健康是本线<strong>第一笔亏损</strong>（前 6 笔全正），连亏计数 1/3（≥3 停手），<strong>尚未触及熔断</strong>。</li></ul><blockquote><p>⚠️ 这一段最容易读出过度结论。执行线的价值不在&quot;这两笔赚没赚&quot;，而在<strong>账本被完整记录下来</strong>： 从 09-01 的第一笔 A 单到 09-24，17 个交易日的每一次决策（含 15 天空仓）都在账本里， 未来任何一次&quot;闸门到底有没有用&quot;的检验，都能拿这段数据说话——<strong>而不是靠回忆和印象</strong>。</p></blockquote><h3 id="复盘-连续-12-日空仓的归因-2026-09-17" tabindex="-1">复盘：连续 12 日空仓的归因（2026-09-17） <a class="header-anchor" href="#复盘-连续-12-日空仓的归因-2026-09-17" aria-label="Permalink to &quot;复盘：连续 12 日空仓的归因（2026-09-17）&quot;">​</a></h3><p>空仓连续到第 12 天时做了一次系统性归因（诊断性复盘，<strong>未改判据 / 未改脚本 / 未动账本</strong>）。 目的不是&quot;证明闸门好&quot;，而是回答一个用户直接抛出的问题：<strong>到底是什么在决定买入还是空仓？</strong></p><p><strong>方法</strong>：把买入/空仓的影响因素拆成 <strong>14 项</strong>（六层机械漏斗 + 熔断项 + 预案换子线规则）， 逐项核验 12 个空仓日是否真的被它拦住；再做<strong>全顺位反事实</strong>（A1→A8 全候选顺位，而非只测第一顺位）。</p><p><strong>结论 1：14 项指标里只有 1 项真正在起作用。</strong></p><table tabindex="0"><thead><tr><th>指标</th><th>12 日中触发次数</th></tr></thead><tbody><tr><td>最高标断板（环境闸门）</td><td><strong>12 / 12</strong></td></tr><tr><td>涨停数不足（&lt;30 冰点）</td><td>0 / 12（区间 32~92）</td></tr><tr><td>候选全一字 / 全不可买</td><td>0~1 / 12</td></tr><tr><td>非主板 / ST / 流通市值 / 仓位 / 现金 / 连亏 等其余 8 项</td><td><strong>0 / 12</strong></td></tr></tbody></table><p>即&quot;有买入 / 没买入&quot;<strong>100% 由单一开关（最高标是否续板）决定</strong>，其余 13 项从未成为约束。</p><blockquote><p>⚠️ <strong>方法教训（已作废的初版结论）</strong>：初版只推演了 A1 单一顺位，漏掉预案顺延规则， 得出&quot;A1 反事实为正、样本不足不能判断&quot;——<strong>错误</strong>。做反事实核验必须走<strong>完整顺位 + 全部指标</strong>， 不能只测首顺位。这条已固化为纪律。</p></blockquote><p><strong>结论 2：闸门是对的——它挡掉的是净亏损。</strong></p><table tabindex="0"><thead><tr><th>口径</th><th>笔数</th><th>均值</th><th>胜负</th></tr></thead><tbody><tr><td>开仓窗口（08-25~09-01）实际 A 单</td><td>5</td><td><strong>+10.46%</strong></td><td>5 胜 0 负</td></tr><tr><td>12 个空仓日&quot;若有闸门则成交&quot;的反事实</td><td>10</td><td><strong>−1.72%</strong></td><td>3 胜 7 负</td></tr></tbody></table><p>反事实用<strong>开盘价近似 09:31</strong>（历史分钟价不可回溯），已声明会<strong>高估可买性</strong>，仅作诊断、不入账本。</p><p><strong>结论 3：断板判定的收盘核验 11/12 正确</strong>，唯一误判是 09-16（早盘判断板、当日午后回封）—— 属&quot;09:31 采样时点 vs 全天事实&quot;的错配，且后果良性（该股次日跌停）。这条直接催生了后续的 &quot;09:31 判读 ≠ 收盘事实&quot;口径备注（见下）。<strong>09-23 该错配第二次出现</strong>（早盘判&quot;未续板&quot;、午后回封收涨停）， 且这一次<strong>改写了当日的高度格局</strong>——详见下方口径备注。</p><p><strong>结论 4：三段 regime 划分</strong>（用于对外解释，非新规则）：</p><table tabindex="0"><thead><tr><th>阶段</th><th>区间</th><th>账本表现</th></tr></thead><tbody><tr><td>退潮期</td><td>08-19 ~ 08-24</td><td>4 日 B</td></tr><tr><td>主升期</td><td>08-25 ~ 09-01</td><td>5 笔 A + 1 日 B</td></tr><tr><td>龙头轮动期</td><td>09-02 ~ 09-18</td><td>13 日 B</td></tr></tbody></table><p><strong>结论 5（用户裁决）：不做影子记账。</strong> 复盘曾提出&quot;空仓日无机会成本记录&quot;为唯一改进项、 建议加一条影子记录（不碰判据）；用户明确否决——<strong>该盲区保留为&quot;已知盲区&quot;，不再作为改进项</strong>。</p><h3 id="一次账本截断事故与恢复-2026-09-22-——本线最重要的一次工程复盘" tabindex="-1">一次账本截断事故与恢复（2026-09-22）——本线最重要的一次工程复盘 <a class="header-anchor" href="#一次账本截断事故与恢复-2026-09-22-——本线最重要的一次工程复盘" aria-label="Permalink to &quot;一次账本截断事故与恢复（2026-09-22）——本线最重要的一次工程复盘&quot;">​</a></h3><p><strong>事件</strong>：尾盘记账任务首次走到&quot;写回账本&quot;这一步即报错退出，<strong>账本被从 25 行截断为 11 行，丢失 14 行</strong> （09-03 ~ 09-22 全部记录）。这是执行线迄今最严重的一次数据事故。</p><p><strong>根因（两个缺陷叠加，缺一不可）</strong>：</p><ol><li><strong>备注字段含未转义的半角逗号</strong>（09-03 起部分行）：CSV 解析时多解析出字段， 读进来就带着一个&quot;不存在的列&quot;，写回时必然抛错；</li><li><strong>非原子写回</strong>：写入用的是&quot;先清空、再逐行写&quot;的方式——<strong>第 12 行抛错时，文件已经被清空了</strong>， 前 11 行是残留、后 14 行永久消失。</li></ol><p><strong>为什么潜伏了 13 天才爆</strong>：09-08 起连续 13 个交易日 B 空仓，任务走的是&quot;无待结算单 → 直接返回&quot;的早退分支， <strong>从未触达写回路径</strong>。缺陷一直在，只是没有机会发作——直到 09-22 两笔 A 单进入结算窗口。</p><p><strong>恢复（三段取证，非&quot;凭记忆重写&quot;）</strong>：</p><table tabindex="0"><thead><tr><th>区段</th><th>恢复来源</th><th>处理</th></tr></thead><tbody><tr><td>08-19 ~ 09-02</td><td>现存文件前段</td><td><strong>逐字节原样保留</strong>，不重写</td></tr><tr><td>09-03 ~ 09-04</td><td>此前回放演练的工作区备份</td><td>取回原文，仅规范化 CSV 引号</td></tr><tr><td>09-07 ~ 09-22</td><td>当日决策任务的完整记录</td><td>按记录重建，<strong>每行加 <code>[RECON-0922]</code> 标记</strong>（声明该行备注非原文）</td></tr></tbody></table><p>恢复后 <strong>25 行 × 9 列全量校验通过</strong>；事故现场文件另存留档，并单独写了事故记录文档。 <strong>数值列（买入价 / 卖出价）全部为原始值、未被重建</strong>——<strong>账本以数值列为权威、不信备注文本</strong>， 这条纪律在事故中救了命：即使备注是重建的，价格序列仍然可信。</p><p><strong>收尾验证</strong>：重跑结算任务成功（幂等复跑返回&quot;无待结算单&quot;、文件哈希前后一致）、 全仓扫描确认<strong>只有结算脚本会程序化读写该账本</strong>、横向排查发现另一处同型非原子写（当前体检干净，属潜伏风险）。</p><p><strong>沉淀（三条，均已写进纪律）</strong>：</p><ol><li><strong>append-only 账本必须用原子写</strong>（写临时文件 → 校验 → 整体替换），任何&quot;先清空再写&quot;都是定时炸弹；</li><li><strong>自由文本字段禁止半角逗号/引号</strong>——这是 CSV 的原生雷区，写入门禁比事后修复便宜得多；</li><li><strong>事故恢复要留痕</strong>：重建行必须带标记、来源必须可追溯，<strong>绝不能把&quot;重建&quot;伪装成&quot;原文&quot;</strong>。</li></ol><blockquote><p>处置说明：以上三条<strong>均为工程加固建议，脚本未改</strong>（改写入方式属实现层，但会动到生产账本路径， 依项目纪律留用户拍板）。<strong>&quot;记录风险 ≠ 忽视风险&quot;</strong>——本轮先如实记录并留证，不擅自改生产链路。</p></blockquote><h3 id="_2026-09-05-口径定稿-双任务拆分-账本只记单价" tabindex="-1">2026-09-05 口径定稿：双任务拆分 + 账本只记单价 <a class="header-anchor" href="#_2026-09-05-口径定稿-双任务拆分-账本只记单价" aria-label="Permalink to &quot;2026-09-05 口径定稿：双任务拆分 + 账本只记单价&quot;">​</a></h3><ul><li><strong>双任务拆分</strong>：09:31 任务只做决策（不结算）、14:57 任务只做记账（不决策），职责互不越界； 账本<strong>只记两个时点的实盘价</strong>（决策时点现价 / 次日 14:57 尾盘现价），<code>ret</code>/<code>excess</code> 字段<strong>永远留空</strong>， 收益由统计层事后按单价推导——从此不存在&quot;执行线自己的收益口径&quot;。</li><li><strong>补跑纪律</strong>：设备故障导致 09-07 双任务未触发，当日以<strong>分钟线还原 09:31 实盘价</strong>补录 （as-of 纪律：绝不引盘后信息回填，也绝不用开盘价凑数）。</li><li><strong>回放能力转正（09-05）</strong>：可对任意历史日全链路回放（盘后结算 → 次日早盘决策 → 尾盘结算）， 回放使用<strong>独立工作区账本</strong>、与生产账本零接触；铁律是&quot;报告必须由数据现算、旧口径不得混入、 数据缺口整段顺延不补录&quot;。</li><li><strong>一处待裁决的显示缺陷</strong>：预案&quot;最高标&quot;字段按&quot;N 天&quot;取最大，遇&quot;N 天 4 板 vs N 天 2 板&quot;会打平误标， 正确排序键应为<strong>连板数</strong>。连续两日复现，已在预案标注真值，<strong>未擅自改脚本</strong>（排序口径属判据，待用户拍板）。</li></ul><p>附带一项工程裁决：候选<strong>决策窗深度取 top5 已足够</strong>（244 交易日口径、机械排序：首个可成交票 rank1 占 86.8%、 rank2 占 11.5%、rank3 占 1.2%、rank4 占 0.4%，<strong>rank≥5 从未被需要</strong>）→ top5 与无限深递补全等，5 不是拍脑袋定的。</p><h3 id="运行期新增口径与工程备注-2026-09-14-09-24" tabindex="-1">运行期新增口径与工程备注（2026-09-14 ~ 09-24） <a class="header-anchor" href="#运行期新增口径与工程备注-2026-09-14-09-24" aria-label="Permalink to &quot;运行期新增口径与工程备注（2026-09-14 ~ 09-24）&quot;">​</a></h3><ul><li><strong>&quot;09:31 判读 ≠ 收盘事实&quot;（2026-09-16 起，重要口径；09-23 第二次暴露）</strong>：环境闸门在 09:31 时点判读&quot;最高标是否续板&quot;， 但<strong>早盘采样与全天事实可能不一致</strong>。09-16 首次出现反例：某高标 09:31 时&quot;高开冲高未封即回落&quot;被判断板， 但当日 <strong>09:36 首封、13:57 回封收涨停</strong>，收盘实为续板——&quot;最高标连续断板&quot;纪录在当日中断。 <strong>09-23 第二次暴露且后果更重</strong>：早盘判&quot;双高标同步未续板&quot;，但其中一只<strong>午后回封涨停收在全天最高</strong>， 实际是 <strong>9 天 7 板续板并接棒成为唯一最高连板</strong>——即 09:31 的账本结论与收盘事实<strong>在高度格局上相反</strong>。 → 两次反例都说明<strong>换手型高标尤易误判</strong>；09:31 的判读只代表<strong>当时</strong>的读数，不等价于收盘结论。 处置：仅作口径备注与记录，<strong>未增设收盘复核环节、未改脚本</strong>（是否增设须用户拍板）。</li><li><strong>交易日校验金标准</strong>：盘中判&quot;今天是否交易日&quot;以<strong>实时行情接口</strong>为准；日线类数据源在盘中会滞后 （当日 bar 尚未生成），<strong>不可用于盘中判交易日</strong>。这条已固化，避免&quot;以为休市而跳过&quot;的误判。 （同源教训在 09-24 又出现一次：日线节点对<strong>个股</strong>当日 K 线滞后、指数正常，当日收盘价须取实时快照节点。）</li><li><strong>日报推送通道有体积硬上限（2026-09-18 起，已三次触发）</strong>：推送通道对 HTML 体积有硬上限（约 2 万字符）， 超限即被拒收；处置顺序为<strong>先渲染量体积 → 再精简正文冗余 → 最后才动样式</strong>。 09-21（20,494 → 19,826 字符）与 09-23（20,849 → 19,777 字符）连续两次靠&quot;精简正文&quot;压回限内， 已在流程里固化为标准动作。另注：同文件重复推送有防重推闸门，<strong>重推前必须先清掉半成品文件</strong>， 否则会静默跳过（09-24 踩过一次）。纯工程项，与策略口径无关。</li><li><strong>账本追加的换行坑（2026-09-23）</strong>：账本文件末尾自带换行，二进制追加时再加一个前导换行会<strong>多出一行空行</strong> （解析出 0 列）。正确做法是<strong>整文件重写 + 逐行校验列数 + 校验末行日期</strong>，写完再复验一遍。 这一条与 09-22 的截断事故同源：<strong>账本写入路径的每一步都要能被校验，而不是&quot;写完就算&quot;</strong>。</li></ul><h2 id="四、与研究线的分工-防口径混用" tabindex="-1">四、与研究线的分工（防口径混用） <a class="header-anchor" href="#四、与研究线的分工-防口径混用" aria-label="Permalink to &quot;四、与研究线的分工（防口径混用）&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>研究线 Step 4</th><th>执行线模拟盘</th></tr></thead><tbody><tr><td>回答</td><td>信号有没有 edge</td><td>edge 能不能落地进规则账户</td></tr><tr><td>买入</td><td>信号日收盘价（理论排板）</td><td>执行日 09:31 市价（真实可成交报价）</td></tr><tr><td>卖出</td><td>T+1 收盘价（理论）</td><td>T+1 14:57 尾盘 ≈ 收盘价</td></tr><tr><td>两者关系</td><td>判据线</td><td>收益通常低于理论值（早盘买点更差），这正是&quot;回测 edge → 实盘折价&quot;要量化的部分</td></tr></tbody></table><h2 id="五、已知局限-诚实项" tabindex="-1">五、已知局限（诚实项） <a class="header-anchor" href="#五、已知局限-诚实项" aria-label="Permalink to &quot;五、已知局限（诚实项）&quot;">​</a></h2><ul><li>E1 仅 n=5，只作方向不作证据；E2/E3 为全量回测，仍是历史口径；</li><li>模拟盘为记账模拟（V1.1 起直记行情价、无撮合引擎），非真实资金——真实世界的滑点、流动性、执行情绪不在模型里；</li><li>Lock 归档 ≠ 证伪：它的正期望是干净的，只是收益结构（右尾）+ 持仓周期不符合当前&quot;短打 + 快速攒样本&quot;的定位。</li></ul><hr><p><strong>互链</strong>：<a href="/A股量化验证/">返回 A股量化验证 首页</a> · 上一篇：<a href="/A股量化验证/6-数据洁净度审计.html">6. 数据洁净度审计</a></p>',76)]))}const p=o(s,[["render",g]]);export{i as __pageData,p as default};
